import{$ as e,B as t,et as n,pt as r}from"./chunks/framework.KBYRAceO.js";import"./chunks/assets.CiIOK21h.js";var i=JSON.parse(`{"title":"VM 가상화 기술 이해하기","description":"가상화 기술과 컨테이너 기반 기술에 대해서 다룹니다.","frontmatter":{"title":"VM 가상화 기술 이해하기","date":"2026-07-19T17:00+09:00","description":"가상화 기술과 컨테이너 기반 기술에 대해서 다룹니다.","tags":["hypervisor","container"]},"headers":[],"relativePath":"posts/understanding-vm-virtualization.md","filePath":"posts/understanding-vm-virtualization.md","lastUpdated":1784760368000}`),a={name:`posts/understanding-vm-virtualization.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="vm-가상화-기술-이해하기" tabindex="-1">VM 가상화 기술 이해하기 <a class="header-anchor" href="#vm-가상화-기술-이해하기" aria-label="Permalink to “VM 가상화 기술 이해하기”">​</a></h1><p>이전 글인 <a href="/posts/beginner-it-infrastructure">기획자도 알아야할 IT 인프라 기초</a> 에서 현대 IT 인프라의 전반적인 지식을 간단하게 살펴보았는데요. 이번 글에서는 인프라의 기초를 담당하는 <mark>가상 머신(VM) 가상화 기술</mark> 과 그 핵심인 <a href="https://aws.amazon.com/ko/what-is/hypervisor/" target="_blank" rel="noreferrer">하이퍼바이저</a> 와 함께 VM 가상화 기술과는 다른 컨테이너 기술에 대해서 알아보려고 해요.</p><h2 id="하이퍼바이저-hypervisor" tabindex="-1">하이퍼바이저(Hypervisor) <a class="header-anchor" href="#하이퍼바이저-hypervisor" aria-label="Permalink to “하이퍼바이저(Hypervisor)”">​</a></h2><p><mark>하이퍼바이저(Hypervisor)</mark> 는 하드웨어를 가상화한 기술이라고 생각하면 돼요. 하이퍼바이저가 하드웨어 위에서 어떻게 실행되는지에 따라 크게 두 가지 유형으로 나눌 수 있어요.</p><h3 id="네이티브-native-하이퍼바이저" tabindex="-1">네이티브(Native) 하이퍼바이저 <a class="header-anchor" href="#네이티브-native-하이퍼바이저" aria-label="Permalink to “네이티브(Native) 하이퍼바이저”">​</a></h3><p>물리 하드웨어에 바로 설치해서 실행되는 방식으로, 호스트 운영체제 없이 직접 하드웨어를 제어하기 때문에 <mark>오버헤드가 적고 리소스 관리가 효율적</mark> 이라 주로 엔터프라이즈 서버 환경 및 클라우드 서비스 인프라에서 사용되고 있어요.</p><ul><li>VMware ESXi</li><li><a href="https://www.redhat.com/ko/topics/virtualization/what-is-KVM" target="_blank" rel="noreferrer">KVM</a></li><li>Xen</li><li><a href="https://learn.microsoft.com/ko-kr/windows-server/virtualization/hyper-v/architecture" target="_blank" rel="noreferrer">Microsoft Hyper-V</a></li></ul><p>예를 들어, <a href="https://docs.aws.amazon.com/ko_kr/AWSEC2/latest/UserGuide/instance-types.html#instance-hypervisor-type" target="_blank" rel="noreferrer">Amazon EC2는 Xen 및 Nitro 하이퍼바이저를 지원</a>하고 있어요. 구형 세대 인스턴스는 <strong>Xen 하이퍼바이저</strong> 방식이고, 신규 세대 인스턴스들은 베어메탈 하드웨어에 가까운 성능을 제공하기 위해서 <a href="https://aws.amazon.com/ko/ec2/nitro/" target="_blank" rel="noreferrer"><strong>Nitro System</strong> 카드를 사용하는 KVM 기반 하이퍼바이저</a>를 자체적으로 개발해서 사용하고 있대요.</p><h3 id="호스트-hosted-하이퍼바이저" tabindex="-1">호스트(Hosted) 하이퍼바이저 <a class="header-anchor" href="#호스트-hosted-하이퍼바이저" aria-label="Permalink to “호스트(Hosted) 하이퍼바이저”">​</a></h3><p>기존의 호스트 운영체제(예: Windows, macOS, Linux) 위에 애플리케이션 형태로 설치되어 실행되는 구조예요. 설치와 구성이 간편하지만 <mark>상대적으로 오버헤드가 커서</mark> 개인 개발 환경이나 테스트 용도로 주로 쓰이고 있어요.</p><ul><li>Oracle VirtualBox</li><li>VMware Workstation</li><li>Parallels Desktop</li></ul><h2 id="컨테이너-기반-가상화-기술" tabindex="-1">컨테이너 기반 가상화 기술 <a class="header-anchor" href="#컨테이너-기반-가상화-기술" aria-label="Permalink to “컨테이너 기반 가상화 기술”">​</a></h2><p>기존 가상 머신과 다르게 <a href="https://aws.amazon.com/ko/compare/the-difference-between-containers-and-virtual-machines/" target="_blank" rel="noreferrer">컨테이너 기반 가상화 기술</a>은 <mark>운영체제(OS) 커널을 공유</mark> 해요. 하드웨어를 가상화하지 않기 때문에 가벼워서 마이크로서비스 아키텍처에 적합하여 컨테이너 기술이 발달하게 되었어요. 지금은 쿠버네티스를 관리하는 <a href="https://k-paas.or.kr/" target="_blank" rel="noreferrer">PaaS 플랫폼을 제공</a>하는 회사도 많은데 이 컨테이너 기술의 발전이 클라우드 서비스 환경 발전을 이루어낸 게 아니에요.</p><p><img src="/images/posts/understanding-vm-virtualization/002.svg" alt="클라우드 가상 머신 위 컨테이너 런타임 계층 구조" loading="lazy"></p><p>다시 정리하면, 현재 대부분의 IT 인프라는 클라우드 회사에서 <strong>하이퍼바이저 기반으로 제공하는 가상 머신</strong> 위에 Docker, containerd, CRI-O 와 같은 <strong>컨테이너 런타임</strong> 으로 애플리케이션을 구동하고 있다고 생각하면 돼요.</p>`,15)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};